begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3631,"word":"litigation","meaning":"訴訟","example":"The lawyer prepared the documents needed for the litigation.","example_zh":"律師準備訴訟所需的文件。","original_meaning":"訴訟","original_example":"The manager leads the team.","original_example_zh":"經理帶領團隊。"},{"source_id":3632,"word":"livelihood","meaning":"生計","example":"The family's livelihood depended on selling handmade baskets.","example_zh":"這家人的生計仰賴販售手工籃子。","original_meaning":"生計","original_example":"Manufacturing has improved.","original_example_zh":"製造業有所改善。"},{"source_id":3633,"word":"lobby","meaning":"遊說","example":"The music clubs decided to lobby the school for a shared rehearsal room.","example_zh":"音樂社團決定遊說學校，爭取共用排練室。","original_meaning":"遊說","original_example":"The market is highly competitive.","original_example_zh":"市場競爭激烈。"},{"source_id":3634,"word":"locomotion","meaning":"移動","example":"The science class compared the locomotion of a fish and a bird.","example_zh":"科學課比較魚與鳥的移動方式。","original_meaning":"移動","original_example":"Mathematics is essential in science.","original_example_zh":"數學在科學中不可或缺。"},{"source_id":3635,"word":"longitude","meaning":"經度","example":"The globe showed lines of longitude meeting at the poles.","example_zh":"地球儀顯示經線在兩極交會。","original_meaning":"經度","original_example":"The medicine helped him recover.","original_example_zh":"藥物幫助他康復。"},{"source_id":3636,"word":"loophole","meaning":"漏洞","example":"The council revised a rule to close a loophole in the competition.","example_zh":"委員會修訂規則，堵住比賽中的漏洞。","original_meaning":"漏洞","original_example":"Memory plays a role in learning.","original_example_zh":"記憶在學習中扮演重要角色。"},{"source_id":3637,"word":"loyalty","meaning":"忠誠","example":"The teammates showed loyalty by supporting the captain after a defeat.","example_zh":"隊友在失利後支持隊長，展現忠誠。","original_meaning":"忠誠","original_example":"The message was clear.","original_example_zh":"訊息非常明確。"},{"source_id":3638,"word":"lubricate","meaning":"潤滑","example":"We used a little oil to lubricate the stiff wheel.","example_zh":"我們用少量油潤滑轉動不順的輪子。","original_meaning":"潤滑","original_example":"Migration affects population trends.","original_example_zh":"移民現象影響人口趨勢。"},{"source_id":3639,"word":"luminous","meaning":"發光的","example":"The luminous lantern guided us along the garden path.","example_zh":"發亮的燈籠引領我們沿花園小徑走。","original_meaning":"發光的","original_example":"Military forces were deployed.","original_example_zh":"軍事部隊已部署到位。"},{"source_id":3640,"word":"magistrate","meaning":"地方法官","example":"The magistrate listened to the neighbors' dispute about the fence.","example_zh":"地方法官聆聽鄰居對柵欄的爭議。","original_meaning":"地方法官","original_example":"The minister gave a speech.","original_example_zh":"部長發表了演說。"},{"source_id":3641,"word":"magnate","meaning":"大亨","example":"The shipping magnate donated books to the seaside school.","example_zh":"航運大亨捐書給海邊學校。","original_meaning":"大亨","original_example":"The mission was successful.","original_example_zh":"任務圓滿成功。"},{"source_id":3642,"word":"mainstream","meaning":"主流的","example":"The band's new album brought its music to a mainstream audience.","example_zh":"樂團的新專輯讓音樂走進主流聽眾群。","original_meaning":"主流的","original_example":"Modern technology is advancing.","original_example_zh":"現代科技日新月異。"},{"source_id":3643,"word":"malaria","meaning":"瘧疾","example":"The clinic displayed a poster about malaria and mosquito protection.","example_zh":"診所展示介紹瘧疾與防蚊的海報。","original_meaning":"瘧疾","original_example":"The mountain is very high.","original_example_zh":"這座山非常高。"},{"source_id":3644,"word":"malice","meaning":"惡意","example":"She realized the mistake came from confusion rather than malice.","example_zh":"她發現那個錯誤源於誤會，而不是惡意。","original_meaning":"惡意","original_example":"Movement is restricted here.","original_example_zh":"此處限制通行。"},{"source_id":3645,"word":"malnutrition","meaning":"營養不良","example":"Relief workers brought nutritious meals to families affected by malnutrition.","example_zh":"救援人員為受營養不良影響的家庭送來營養餐食。","original_meaning":"營養不良","original_example":"Music can influence mood.","original_example_zh":"音樂能影響情緒。"},{"source_id":3646,"word":"mammoth","meaning":"巨大的","example":"Clearing the huge pile of branches was a mammoth task for the team.","example_zh":"清理巨大枝條堆，對小組是項艱鉅的大工程。","original_meaning":"巨大的","original_example":"The nation celebrated independence.","original_example_zh":"全國慶祝獨立。"},{"source_id":3647,"word":"maneuver","meaning":"策略；調度","example":"One clever maneuver opened a path for the queen on the chessboard.","example_zh":"棋盤上一個巧妙調度，替皇后打開路線。","original_meaning":"策略","original_example":"Nature provides many resources.","original_example_zh":"大自然提供了許多資源。"},{"source_id":3648,"word":"manifesto","meaning":"宣言","example":"The council wrote a manifesto promising a cleaner, greener school.","example_zh":"學生會撰寫宣言，承諾打造更乾淨綠意的校園。","original_meaning":"宣言","original_example":"Negotiation is key to agreement.","original_example_zh":"協商是達成協議的關鍵。"},{"source_id":3649,"word":"manipulation","meaning":"操縱；操作","example":"The technician demonstrated careful manipulation of the tiny robot arm.","example_zh":"技師示範如何仔細操作小型機械手臂。","original_meaning":"操縱","original_example":"The network is stable.","original_example_zh":"網路很穩定。"},{"source_id":3650,"word":"manuscript","meaning":"手稿","example":"The writer showed us the manuscript of her first story.","example_zh":"作家向我們展示她第一篇故事的手稿。","original_meaning":"手稿","original_example":"The news spread quickly.","original_example_zh":"消息迅速傳開。"},{"source_id":3651,"word":"marathon","meaning":"馬拉松","example":"The runners trained for months before their first marathon.","example_zh":"跑者在第一次馬拉松前訓練了好幾個月。","original_meaning":"馬拉松","original_example":"Nutrition affects health.","original_example_zh":"營養影響健康。"},{"source_id":3652,"word":"margin","meaning":"邊際；頁邊","example":"Leave a wide margin around the edge of your sketch.","example_zh":"在草圖四周留寬一點的頁邊。","original_meaning":"邊際","original_example":"The object is made of metal.","original_example_zh":"該物體由金屬製成。"},{"source_id":3653,"word":"marketplace","meaning":"市場","example":"The marketplace filled with farmers selling fresh produce.","example_zh":"市場裡擠滿販售新鮮農產品的農民。","original_meaning":"市場","original_example":"Observation helps learning.","original_example_zh":"觀察有助於學習。"},{"source_id":3654,"word":"massacre","meaning":"屠殺","example":"The class visited a memorial to the victims of a massacre.","example_zh":"班上參訪紀念屠殺受害者的紀念館。","original_meaning":"屠殺","original_example":"The office is closed today.","original_example_zh":"今天辦公室休假。"},{"source_id":3655,"word":"maternal","meaning":"母性的","example":"The bird showed maternal care as she sheltered her chicks from rain.","example_zh":"母鳥遮護雛鳥免於淋雨，展現母性的照顧。","original_meaning":"母性的","original_example":"Operation was successful.","original_example_zh":"手術成功。"},{"source_id":3656,"word":"maternity","meaning":"產假","example":"The teacher took maternity leave after her baby was born.","example_zh":"寶寶出生後，老師請了產假。","original_meaning":"產假","original_example":"Opportunity comes to those prepared.","original_example_zh":"機會屬於有準備的人。"},{"source_id":3657,"word":"medication","meaning":"藥物","example":"The pharmacist checked the medication before giving it to the patient.","example_zh":"藥師把藥物交給病人前先仔細核對。","original_meaning":"藥物","original_example":"The pharmacist explained when I should take the medication.","original_example_zh":"藥師說明了我應該在什麼時候服藥。"},{"source_id":3658,"word":"medieval","meaning":"中世紀的","example":"The museum displayed a medieval bridge made of stone.","example_zh":"博物館展示一座中世紀石橋的模型。","original_meaning":"中世紀的","original_example":"The outcome was unexpected.","original_example_zh":"結果出乎意料。"},{"source_id":3659,"word":"memoir","meaning":"回憶錄","example":"Her memoir described the years she spent restoring old instruments.","example_zh":"她的回憶錄描述修復老樂器的那段歲月。","original_meaning":"回憶錄","original_example":"The owner sold the business.","original_example_zh":"老闆賣掉了這家店。"},{"source_id":3660,"word":"memorial","meaning":"紀念碑","example":"The memorial stood beside the tree planted in the teacher's honor.","example_zh":"紀念碑矗立在紀念老師而種的樹旁。","original_meaning":"紀念碑","original_example":"The painting is beautiful.","original_example_zh":"這幅畫很美。"},{"source_id":3661,"word":"mentor","meaning":"導師；指導者","example":"The mentor helped the student turn a rough idea into a working model.","example_zh":"導師幫學生把粗略想法變成能運作的模型。","original_meaning":"導師；指導者","original_example":"My mentor reviewed my application and pointed out an unclear paragraph.","original_example_zh":"指導老師看過我的申請資料，指出一段不清楚的內容。"},{"source_id":3662,"word":"merchandise","meaning":"商品","example":"The shopkeeper arranged the handmade merchandise on wooden shelves.","example_zh":"店主把手工商品陳列在木架上。","original_meaning":"商品","original_example":"The patient recovered quickly.","original_example_zh":"病患很快康復了。"},{"source_id":3663,"word":"merger","meaning":"合併","example":"The merger of two small clubs created a stronger orchestra.","example_zh":"兩個小社團合併，組成更有實力的管弦樂團。","original_meaning":"合併","original_example":"The performance was excellent.","original_example_zh":"表現非常出色。"},{"source_id":3664,"word":"metabolism","meaning":"新陳代謝","example":"The students used a cell model to study metabolism.","example_zh":"學生使用細胞模型研究新陳代謝。","original_meaning":"新陳代謝","original_example":"Enough sleep supports a healthy metabolism as much as regular exercise does.","original_example_zh":"充足睡眠和規律運動一樣，有助於健康的新陳代謝。"},{"source_id":3665,"word":"metaphor","meaning":"隱喻","example":"The poem used a growing tree as a metaphor for friendship.","example_zh":"這首詩以成長的樹隱喻友誼。","original_meaning":"隱喻","original_example":"The player scored a goal.","original_example_zh":"球員進了一球。"},{"source_id":3666,"word":"methodology","meaning":"方法論","example":"The class agreed on a methodology for counting birds in the wetland.","example_zh":"班上商定一套計算濕地鳥類的方法。","original_meaning":"方法論","original_example":"The policy affects many people.","original_example_zh":"這項政策影響許多人。"},{"source_id":3667,"word":"metropolitan","meaning":"都會的","example":"The metropolitan library served readers from across the city.","example_zh":"都會圖書館服務來自全市的讀者。","original_meaning":"都會的","original_example":"The population is growing.","original_example_zh":"人口正在增長。"},{"source_id":3668,"word":"microbe","meaning":"微生物","example":"The model showed a microbe too small to see without magnification.","example_zh":"模型呈現肉眼難以看見的微生物。","original_meaning":"微生物","original_example":"The position is available.","original_example_zh":"這個職位尚有空缺。"},{"source_id":3669,"word":"microscope","meaning":"顯微鏡","example":"We used a microscope to examine a thin leaf sample.","example_zh":"我們用顯微鏡觀察薄薄的葉片樣本。","original_meaning":"顯微鏡","original_example":"Practice improves skills.","original_example_zh":"練習能提升技能。"},{"source_id":3670,"word":"migration","meaning":"遷移","example":"The students watched the birds' migration along the coast.","example_zh":"學生觀察鳥類沿海岸遷徙。","original_meaning":"遷移","original_example":"The prediction was accurate.","original_example_zh":"預測非常準確。"},{"source_id":3671,"word":"militia","meaning":"民兵","example":"The history exhibit showed a militia formed by local adults.","example_zh":"歷史展覽呈現由當地成年人組成的民兵。","original_meaning":"民兵","original_example":"The pressure increased suddenly.","original_example_zh":"壓力突然增加。"},{"source_id":3672,"word":"millennium","meaning":"千年","example":"The display traced changes in the town over a millennium.","example_zh":"展示追溯城鎮一千年來的變化。","original_meaning":"千年","original_example":"The process takes time.","original_example_zh":"這個過程需要時間。"},{"source_id":3673,"word":"mineral","meaning":"礦物質；礦物","example":"The students examined a mineral with a magnifying glass.","example_zh":"學生用放大鏡觀察一塊礦物。","original_meaning":"礦物質；礦物","original_example":"The label lists the minerals contained in the bottled water.","original_example_zh":"標籤列出瓶裝水所含的礦物質。"},{"source_id":3674,"word":"ministry","meaning":"部會","example":"The education ministry supported the new school library.","example_zh":"教育部門支持新校園圖書館。","original_meaning":"部會","original_example":"The program was successful.","original_example_zh":"該計畫很成功。"},{"source_id":3675,"word":"minority","meaning":"少數；少數群體","example":"Only a minority of the students chose the longer hiking route.","example_zh":"只有少數學生選擇較長的健行路線。","original_meaning":"少數；少數群體","original_example":"Only a small minority chose to present the report alone.","original_example_zh":"只有少數人選擇獨自上台報告。"},{"source_id":3676,"word":"misconception","meaning":"誤解","example":"The experiment corrected our misconception about how plants take in water.","example_zh":"實驗修正了我們對植物吸收水分的誤解。","original_meaning":"誤解","original_example":"The project is ongoing.","original_example_zh":"該專案正在進行中。"},{"source_id":3677,"word":"missionary","meaning":"傳教士","example":"The museum displayed a missionary's old journal and travel bag.","example_zh":"博物館展示一位傳教士的舊日記與旅行袋。","original_meaning":"傳教士","original_example":"The property is valuable.","original_example_zh":"這處房產很有價值。"},{"source_id":3678,"word":"mobilize","meaning":"動員","example":"The club helped mobilize neighbors to clean the polluted stream.","example_zh":"社團協助動員鄰居，清理受污染的小溪。","original_meaning":"動員","original_example":"The proposal was accepted.","original_example_zh":"該提案獲得通過。"},{"source_id":3679,"word":"modernize","meaning":"現代化","example":"The town planned to modernize the old library while preserving its stone walls.","example_zh":"城鎮計畫保留石牆，同時讓老圖書館現代化。","original_meaning":"現代化","original_example":"The quality is excellent.","original_example_zh":"品質極佳。"},{"source_id":3680,"word":"molecule","meaning":"分子","example":"The colored balls represented the atoms in a molecule.","example_zh":"彩球代表分子中的原子。","original_meaning":"分子","original_example":"The reaction was quick.","original_example_zh":"反應迅速。"},{"source_id":3681,"word":"monarch","meaning":"君主","example":"The portrait showed the monarch at a formal court ceremony.","example_zh":"肖像描繪君主參加正式宮廷典禮。","original_meaning":"君主","original_example":"The research is ongoing.","original_example_zh":"研究仍在進行中。"},{"source_id":3682,"word":"monastery","meaning":"修道院","example":"The quiet monastery stood among the trees above the valley.","example_zh":"寧靜修道院坐落在山谷上方的樹林中。","original_meaning":"修道院","original_example":"The result was surprising.","original_example_zh":"結果令人驚訝。"},{"source_id":3683,"word":"monetary","meaning":"貨幣的；金錢的","example":"The club received a monetary award for restoring the pond.","example_zh":"社團因復育池塘而獲得獎金。","original_meaning":"貨幣的","original_example":"The risk is high.","original_example_zh":"風險很高。"},{"source_id":3684,"word":"monopolize","meaning":"壟斷；獨佔","example":"Please do not monopolize the conversation during our club meeting.","example_zh":"社團會議時，請不要獨佔發言時間。","original_meaning":"壟斷","original_example":"The role is important.","original_example_zh":"這個角色很重要。"},{"source_id":3685,"word":"monument","meaning":"紀念碑","example":"The old stone monument marked the entrance to the town square.","example_zh":"古老石碑標示城鎮廣場的入口。","original_meaning":"紀念碑","original_example":"The rule must be followed.","original_example_zh":"必須遵守規則。"},{"source_id":3686,"word":"morality","meaning":"道德","example":"The story raised questions about morality and keeping promises.","example_zh":"故事引發關於道德與守信的問題。","original_meaning":"道德","original_example":"Safety is a priority.","original_example_zh":"安全是首要考量。"},{"source_id":3687,"word":"mortality","meaning":"死亡率","example":"The researchers compared mortality rates in the two regions.","example_zh":"研究人員比較兩個地區的死亡率。","original_meaning":"死亡率","original_example":"Science explains natural phenomena.","original_example_zh":"科學解釋自然現象。"},{"source_id":3688,"word":"mortgage","meaning":"房貸","example":"The family discussed the mortgage with the bank before buying the house.","example_zh":"這家人買房前，先和銀行討論房貸。","original_meaning":"房貸","original_example":"The system is efficient.","original_example_zh":"該系統運作高效。"},{"source_id":3689,"word":"mosque","meaning":"清真寺","example":"The visitors admired the mosque's dome from the courtyard.","example_zh":"訪客從庭院欣賞清真寺的圓頂。","original_meaning":"清真寺","original_example":"The mosque is a place of worship for Muslims.","original_example_zh":"清真寺是穆斯林的禮拜場所。"},{"source_id":3690,"word":"motivation","meaning":"動機","example":"Helping the younger students became her motivation for joining the club.","example_zh":"幫助年幼學生，成為她加入社團的動機。","original_meaning":"動機","original_example":"Her motivation comes from her passion for learning.","original_example_zh":"她的動力源於對學習的熱情。"},{"source_id":3691,"word":"multinational","meaning":"跨國的","example":"The multinational team brought together researchers from several countries.","example_zh":"跨國研究團隊集合來自數個國家的研究人員。","original_meaning":"跨國的","original_example":"He works for a multinational company.","original_example_zh":"他在一家跨國公司工作。"},{"source_id":3692,"word":"municipality","meaning":"市政；地方自治政府","example":"The municipality repaired the path near the public library.","example_zh":"地方自治政府修復了公共圖書館附近的步道。","original_meaning":"市政","original_example":"The municipality is responsible for local services.","original_example_zh":"市政府負責提供地方服務。"},{"source_id":3693,"word":"mutation","meaning":"突變","example":"The class used colored beads to represent a mutation in a gene.","example_zh":"班上用彩珠代表基因中的一次突變。","original_meaning":"突變","original_example":"A mutation in the gene caused the disease.","original_example_zh":"基因突變導致了這種疾病。"},{"source_id":3694,"word":"narrative","meaning":"敘事","example":"The museum's narrative followed one family's journey across the sea.","example_zh":"博物館的敘事追隨一個家庭跨海的旅程。","original_meaning":"敘事","original_example":"The novel has a strong narrative structure.","original_example_zh":"這部小說具有強烈的敘事結構。"},{"source_id":3695,"word":"nationality","meaning":"國籍","example":"The travel form included a space for nationality.","example_zh":"旅行表格裡有填寫國籍的欄位。","original_meaning":"國籍","original_example":"Her nationality is Canadian.","original_example_zh":"她的國籍是加拿大。"},{"source_id":3696,"word":"navigate","meaning":"導航","example":"The guide used a map to navigate through the forest.","example_zh":"嚮導使用地圖在森林裡辨路。","original_meaning":"導航","original_example":"We used a map to navigate the city.","original_example_zh":"我們利用地圖在城市中導航。"},{"source_id":3697,"word":"negligence","meaning":"疏忽","example":"Negligence during maintenance left the bicycle with a loose brake.","example_zh":"維修時的疏忽，讓腳踏車煞車仍然鬆動。","original_meaning":"疏忽","original_example":"The accident was caused by negligence.","original_example_zh":"這起事故是由疏忽造成的。"},{"source_id":3698,"word":"neutrality","meaning":"中立","example":"The mediator maintained neutrality while listening to both sides.","example_zh":"調解者聆聽雙方意見時保持中立。","original_meaning":"中立","original_example":"The country maintained neutrality during the war.","original_example_zh":"該國在戰爭期間維持中立。"},{"source_id":3699,"word":"nitrogen","meaning":"氮","example":"The lesson introduced nitrogen as a gas found in the air.","example_zh":"課程介紹氮是一種存在於空氣中的氣體。","original_meaning":"氮","original_example":"Nitrogen is essential for plant growth.","original_example_zh":"氮對植物生長至關重要。"},{"source_id":3700,"word":"nobility","meaning":"貴族","example":"The portraits showed members of the nobility in formal court attire.","example_zh":"肖像呈現貴族穿著正式宮廷服裝的模樣。","original_meaning":"貴族","original_example":"The nobility lived in grand palaces.","original_example_zh":"貴族們居住在宏偉的宮殿中。"},{"source_id":3701,"word":"nominate","meaning":"提名","example":"The club voted to nominate Nora for the volunteer award.","example_zh":"社團投票提名諾拉角逐志工獎。","original_meaning":"提名","original_example":"She was nominated for the award.","original_example_zh":"她獲提名角逐該獎項。"},{"source_id":3702,"word":"nonchalant","meaning":"漫不經心的；若無其事的","example":"The pianist seemed nonchalant before the difficult performance.","example_zh":"鋼琴家在困難演出前，看起來若無其事。","original_meaning":"漫不經心的","original_example":"He gave a nonchalant shrug.","original_example_zh":"他漫不經心地聳了聳肩。"},{"source_id":3703,"word":"nonprofit","meaning":"非營利的","example":"The nonprofit group repaired bicycles for children in the community.","example_zh":"非營利團體為社區孩子修理腳踏車。","original_meaning":"非營利的","original_example":"They started a nonprofit organization.","original_example_zh":"他們創立了一個非營利組織。"},{"source_id":3704,"word":"norm","meaning":"規範；常態","example":"Sharing tools fairly became the norm in our workshop.","example_zh":"公平共用工具，成為工坊裡的常態。","original_meaning":"規範","original_example":"Wearing masks became the new norm.","original_example_zh":"戴口罩成了新常態。"},{"source_id":3705,"word":"notable","meaning":"顯著的","example":"The seedlings showed notable growth after a week of care.","example_zh":"細心照顧一週後，幼苗明顯長大。","original_meaning":"顯著的","original_example":"She made a notable contribution to science.","original_example_zh":"她對科學作出了顯著貢獻。"},{"source_id":3706,"word":"notification","meaning":"通知","example":"A notification reminded us that the library workshop would begin soon.","example_zh":"一則通知提醒我們，圖書館工作坊即將開始。","original_meaning":"通知","original_example":"I received a notification on my phone.","original_example_zh":"我收到手機通知。"},{"source_id":3707,"word":"notorious","meaning":"惡名昭彰的","example":"The old road was notorious for its deep potholes.","example_zh":"那條老路因坑洞深而惡名昭彰。","original_meaning":"惡名昭彰的","original_example":"The criminal was notorious for his crimes.","original_example_zh":"該罪犯因其罪行而臭名昭著。"},{"source_id":3708,"word":"novelty","meaning":"新奇","example":"The novelty of the tiny robot attracted a crowd at the fair.","example_zh":"小機器人的新奇感，在市集吸引了一群人。","original_meaning":"新奇","original_example":"The toy was bought for its novelty.","original_example_zh":"買這玩具是為了它的新奇感。"},{"source_id":3709,"word":"nuclear","meaning":"核能的","example":"The science museum introduced nuclear energy through a simple model.","example_zh":"科學博物館用簡單模型介紹核能。","original_meaning":"核能的","original_example":"Nuclear energy can produce large amounts of power.","original_example_zh":"核能可以產生大量電力。"},{"source_id":3710,"word":"nurture","meaning":"培育","example":"We carefully nurture the young trees planted beside the school.","example_zh":"我們細心培育種在學校旁的幼樹。","original_meaning":"培育","original_example":"Parents nurture their children with care.","original_example_zh":"父母悉心養育子女。"},{"source_id":3711,"word":"oath","meaning":"宣誓","example":"The new judge took an oath to serve fairly.","example_zh":"新任法官宣誓公正服務。","original_meaning":"宣誓","original_example":"He took an oath before starting his duty.","original_example_zh":"他在開始執勤前宣誓。"},{"source_id":3712,"word":"obedience","meaning":"服從","example":"The dog's obedience improved with gentle, consistent training.","example_zh":"透過溫和且一致的訓練，小狗更能聽從指令。","original_meaning":"服從","original_example":"Obedience is expected in the military.","original_example_zh":"軍中要求服從。"},{"source_id":3713,"word":"objection","meaning":"反對","example":"Nora raised an objection to leaving one classmate out.","example_zh":"諾拉對排除一位同學提出反對。","original_meaning":"反對","original_example":"She raised an objection to the proposal.","original_example_zh":"她對該提案提出異議。"},{"source_id":3714,"word":"obscure","meaning":"模糊的","example":"The old map's obscure markings were difficult to interpret.","example_zh":"舊地圖模糊的記號很難判讀。","original_meaning":"模糊的","original_example":"The meaning of the poem was obscure.","original_example_zh":"這首詩的含義晦澀難懂。"},{"source_id":3715,"word":"observatory","meaning":"天文台","example":"Our class visited the observatory to study the night sky.","example_zh":"我們班參訪天文台，研究夜空。","original_meaning":"天文台","original_example":"The observatory allows scientists to study stars.","original_example_zh":"天文台讓科學家得以研究星辰。"},{"source_id":3716,"word":"obsession","meaning":"痴迷","example":"Her obsession with collecting shells filled every shelf in the room.","example_zh":"她痴迷收集貝殼，房裡每個架子都擺滿了收藏。","original_meaning":"痴迷","original_example":"His obsession with perfection caused stress.","original_example_zh":"他對完美的執著導致了壓力。"},{"source_id":3717,"word":"obstruction","meaning":"阻礙","example":"We moved the boxes to remove an obstruction from the doorway.","example_zh":"我們搬開箱子，清除門口的阻礙。","original_meaning":"阻礙","original_example":"The roadblock created an obstruction.","original_example_zh":"路障造成阻礙。"},{"source_id":3718,"word":"occupation","meaning":"佔領","example":"The exhibit described the town's years under foreign occupation.","example_zh":"展覽介紹城鎮受到外來佔領的那段歲月。","original_meaning":"佔領","original_example":"The occupation lasted for many years.","original_example_zh":"佔領持續了許多年。"},{"source_id":3719,"word":"occurrence","meaning":"發生","example":"The occurrence of a small leak led us to inspect the roof.","example_zh":"一次小漏水，讓我們檢查屋頂。","original_meaning":"發生","original_example":"The occurrence of errors is rare.","original_example_zh":"出錯的情況很少見。"},{"source_id":3720,"word":"offspring","meaning":"後代","example":"The swan guided her offspring across the quiet pond.","example_zh":"天鵝帶領後代游過安靜池塘。","original_meaning":"後代","original_example":"The animal protects its offspring.","original_example_zh":"這隻動物保護著它的後代。"},{"source_id":3721,"word":"oligarchy","meaning":"寡頭政治","example":"The lesson described an oligarchy controlled by a few powerful families.","example_zh":"課程介紹由少數強大家族控制的寡頭政體。","original_meaning":"寡頭政治","original_example":"The country was ruled by an oligarchy.","original_example_zh":"該國由寡頭政治統治。"},{"source_id":3722,"word":"omen","meaning":"預兆","example":"In the tale, the returning swallows were a good omen.","example_zh":"故事裡，燕子歸來被視為好預兆。","original_meaning":"預兆","original_example":"Dark clouds were seen as an omen.","original_example_zh":"烏雲被視為不祥之兆。"},{"source_id":3723,"word":"omission","meaning":"遺漏","example":"We noticed the omission of a flashlight while checking the camping list.","example_zh":"檢查露營清單時，我們發現漏列了手電筒。","original_meaning":"遺漏","original_example":"The report contained an important omission.","original_example_zh":"該報告有項重要的遺漏。"},{"source_id":3724,"word":"onset","meaning":"開始","example":"The onset of winter made us cover the young plants.","example_zh":"冬天開始時，我們替幼苗蓋上保護罩。","original_meaning":"開始","original_example":"The onset of winter was sudden.","original_example_zh":"冬天的來臨十分突然。"},{"source_id":3725,"word":"opaque","meaning":"不透明的","example":"Unlike the clear container, the opaque box hid its contents.","example_zh":"不像透明容器，不透明的盒子把內容物遮住了。","original_meaning":"不透明的","original_example":"The glass is opaque and cannot be seen through.","original_example_zh":"玻璃不透明，無法透視。"},{"source_id":3726,"word":"oppression","meaning":"壓迫","example":"The museum explained how villagers resisted years of oppression.","example_zh":"博物館說明村民如何反抗多年壓迫。","original_meaning":"壓迫","original_example":"People protested against oppression.","original_example_zh":"人們抗議壓迫。"},{"source_id":3727,"word":"optimism","meaning":"樂觀","example":"With optimism, the team began rebuilding the broken model.","example_zh":"小組抱持樂觀，開始重建壞掉的模型。","original_meaning":"樂觀","original_example":"Her optimism kept her going.","original_example_zh":"她的樂觀態度讓她堅持下去。"},{"source_id":3728,"word":"orbit","meaning":"軌道","example":"The classroom model showed the Moon's orbit around Earth.","example_zh":"教室模型展示月球繞地球的軌道。","original_meaning":"軌道","original_example":"The satellite moves in orbit around Earth.","original_example_zh":"衛星在地球軌道上運行。"},{"source_id":3729,"word":"ordeal","meaning":"磨難","example":"The long journey through the storm was an ordeal for the travelers.","example_zh":"穿越暴風雨的漫長旅程，是旅人們的一場磨難。","original_meaning":"磨難","original_example":"He survived a terrible ordeal.","original_example_zh":"他熬過了可怕的磨難。"},{"source_id":3730,"word":"ordinance","meaning":"法令","example":"The town ordinance protected the old trees in the square.","example_zh":"城鎮法令保護廣場上的老樹。","original_meaning":"法令","original_example":"The city passed a new ordinance.","original_example_zh":"該市通過了一項新條例。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-litigation-01-v1","level":"senior","word":"litigation","sort_order":1,"sense":"訴訟","alt_zh":"成年律師在明亮辦公室整理訴訟文件與建物照片，文字不可辨識。","example":"The lawyer prepared the documents needed for the litigation.","example_zh":"律師準備訴訟所需的文件。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/litigation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-livelihood-01-v1","level":"senior","word":"livelihood","sort_order":1,"sense":"生計","alt_zh":"家人在市集合作編織、整理並販售手工籃子，神情認真而有尊嚴。","example":"The family's livelihood depended on selling handmade baskets.","example_zh":"這家人的生計仰賴販售手工籃子。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/livelihood-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lobby-01-v1","level":"senior","word":"lobby","sort_order":1,"sense":"遊說","alt_zh":"高中社團代表禮貌向校長展示共用音樂室模型，說明大家的需求。","example":"The music clubs decided to lobby the school for a shared rehearsal room.","example_zh":"音樂社團決定遊說學校，爭取共用排練室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lobby-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-locomotion-01-v1","level":"senior","word":"locomotion","sort_order":1,"sense":"移動","alt_zh":"老師與高中生在自然展館觀察游動魚與展翅鳥的教學模型，單一展示空間。","example":"The science class compared the locomotion of a fish and a bird.","example_zh":"科學課比較魚與鳥的移動方式。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/locomotion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-longitude-01-v1","level":"senior","word":"longitude","sort_order":1,"sense":"經度","alt_zh":"高中生觀察完全無字的地球儀，清楚可見一條條從北極連到南極的經線。","example":"The globe showed lines of longitude meeting at the poles.","example_zh":"地球儀顯示經線在兩極交會。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/longitude-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-loophole-01-v1","level":"senior","word":"loophole","sort_order":1,"sense":"漏洞","alt_zh":"高中學生委員會與老師一起修改無可讀文字的競賽規則，讓各隊公平參與。","example":"The council revised a rule to close a loophole in the competition.","example_zh":"委員會修訂規則，堵住比賽中的漏洞。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/loophole-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-loyalty-01-v1","level":"senior","word":"loyalty","sort_order":1,"sense":"忠誠","alt_zh":"高中球隊在比賽失利後圍著隊長，拍拍肩膀、彼此鼓勵。","example":"The teammates showed loyalty by supporting the captain after a defeat.","example_zh":"隊友在失利後支持隊長，展現忠誠。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/loyalty-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lubricate-01-v1","level":"senior","word":"lubricate","sort_order":1,"sense":"潤滑","alt_zh":"老師在安全修理桌旁指導高中生，替小模型車輪軸加少量潤滑油。","example":"We used a little oil to lubricate the stiff wheel.","example_zh":"我們用少量油潤滑轉動不順的輪子。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lubricate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-luminous-01-v1","level":"senior","word":"luminous","sort_order":1,"sense":"發光的","alt_zh":"成年老師提著柔亮燈籠，帶高中生在安全花園步道上夜間觀察。","example":"The luminous lantern guided us along the garden path.","example_zh":"發亮的燈籠引領我們沿花園小徑走。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/luminous-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-magistrate-01-v1","level":"senior","word":"magistrate","sort_order":1,"sense":"地方法官","alt_zh":"成年地方法官在地方小法庭平靜聽兩位成年鄰居說明，桌上有柵欄照片。","example":"The magistrate listened to the neighbors' dispute about the fence.","example_zh":"地方法官聆聽鄰居對柵欄的爭議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/magistrate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-magnate-01-v1","level":"senior","word":"magnate","sort_order":1,"sense":"大亨","alt_zh":"成年航運企業家把書箱交給海邊學校老師，後方港口有商船，無公司標誌。","example":"The shipping magnate donated books to the seaside school.","example_zh":"航運大亨捐書給海邊學校。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/magnate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-mainstream-01-v1","level":"senior","word":"mainstream","sort_order":1,"sense":"主流的","alt_zh":"成年青年樂團在社區音樂廳向廣泛年齡觀眾演出，氣氛熱烈，無文字或標誌。","example":"The band's new album brought its music to a mainstream audience.","example_zh":"樂團的新專輯讓音樂走進主流聽眾群。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/mainstream-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-malaria-01-v1","level":"senior","word":"malaria","sort_order":1,"sense":"瘧疾","alt_zh":"成年衛教人員向訪客指著只有蚊子與蚊帳圖示的海報，無文字、病人痛苦或用藥細節。","example":"The clinic displayed a poster about malaria and mosquito protection.","example_zh":"診所展示介紹瘧疾與防蚊的海報。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/malaria-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-malice-01-v1","level":"senior","word":"malice","sort_order":1,"sense":"惡意","alt_zh":"兩名高中生在老師陪同下釐清誤拿工具的誤會，原本生氣的人逐漸放鬆。","example":"She realized the mistake came from confusion rather than malice.","example_zh":"她發現那個錯誤源於誤會，而不是惡意。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/malice-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-malnutrition-01-v1","level":"senior","word":"malnutrition","sort_order":1,"sense":"營養不良","alt_zh":"成年志工向家庭提供均衡餐食與乾淨飲水，人物外觀自然、有尊嚴，無消瘦痛苦特寫。","example":"Relief workers brought nutritious meals to families affected by malnutrition.","example_zh":"救援人員為受營養不良影響的家庭送來營養餐食。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/malnutrition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-mammoth-01-v1","level":"senior","word":"mammoth","sort_order":1,"sense":"巨大的","alt_zh":"幾名高中志工與成年領隊站在非常巨大的倒枝堆旁，準備分工清理；不出現猛獁象或其他史前動物。","example":"Clearing the huge pile of branches was a mammoth task for the team.","example_zh":"清理巨大枝條堆，對小組是項艱鉅的大工程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/mammoth-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-maneuver-01-v1","level":"senior","word":"maneuver","sort_order":1,"sense":"策略；調度","alt_zh":"高中棋手在木製棋盤前移動一枚棋子，老師向同學指出皇后前方打開的空間。","example":"One clever maneuver opened a path for the queen on the chessboard.","example_zh":"棋盤上一個巧妙調度，替皇后打開路線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/maneuver-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-manifesto-01-v1","level":"senior","word":"manifesto","sort_order":1,"sense":"宣言","alt_zh":"高中學生會在校園花園模型旁一起整理宣言文件，紙上只有模糊線條與葉片圖示。","example":"The council wrote a manifesto promising a cleaner, greener school.","example_zh":"學生會撰寫宣言，承諾打造更乾淨綠意的校園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/manifesto-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-manipulation-01-v1","level":"senior","word":"manipulation","sort_order":1,"sense":"操縱；操作","alt_zh":"成年技師指導高中生用控制器精準移動小型機械手臂，輕提脆弱模型。","example":"The technician demonstrated careful manipulation of the tiny robot arm.","example_zh":"技師示範如何仔細操作小型機械手臂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/manipulation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-manuscript-01-v1","level":"senior","word":"manuscript","sort_order":1,"sense":"手稿","alt_zh":"成年女作家在工作室向高中生展示有修改痕跡的手稿，字跡不可讀。","example":"The writer showed us the manuscript of her first story.","example_zh":"作家向我們展示她第一篇故事的手稿。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/manuscript-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-marathon-01-v1","level":"senior","word":"marathon","sort_order":1,"sense":"馬拉松","alt_zh":"成年跑者在安全公園步道有節奏地訓練，教練與水站在旁，無比賽數字。","example":"The runners trained for months before their first marathon.","example_zh":"跑者在第一次馬拉松前訓練了好幾個月。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/marathon-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-margin-01-v1","level":"senior","word":"margin","sort_order":1,"sense":"邊際；頁邊","alt_zh":"高中生在美術課用尺檢查草圖四周保留的寬空白邊，無文字。","example":"Leave a wide margin around the edge of your sketch.","example_zh":"在草圖四周留寬一點的頁邊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/margin-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-marketplace-01-v1","level":"senior","word":"marketplace","sort_order":1,"sense":"市場","alt_zh":"熱鬧市集中，成年農民擺出新鮮蔬菜水果，家人與高中生挑選。","example":"The marketplace filled with farmers selling fresh produce."